begin
 select payload into current_payload from public.mundinho_content where key='page:progression' for update;
 if (current_payload->'items') @> patches then return; end if;
 if md5(current_payload::text) is distinct from '6a91e0864524e7e873aa35f6e88de498' then raise exception 'Progression changed since snapshot; abort destination migration'; end if;
 if jsonb_array_length(current_payload->'items')<>127 then raise exception 'Expected 127 existing milestones'; end if;
 update public.mundinho_content set payload=jsonb_set(current_payload,'{items}',(
 select jsonb_agg(coalesce(p.value,i.value) order by i.ordinality)
 from jsonb_array_elements(current_payload->'items') with ordinality i(value,ordinality)
 left join jsonb_array_elements(patches) p(value) on p.value->>'id'=i.value->>'id'))
 where key='page:progression';
end $migration$;
